222	Expected<CoreRuntimeOp> RuntimeFallbackOpHandler::MakeOp(string_view op_name) {
223	  // NOTE(fishx): Copying string here will cost extra overhead in graph
224	  // execution. Because in current implementation, we needs to prepare the op
225	  // before each executions.
226	  // TODO(fishx): Avoid this heap allocation by getting op registration
227	  // information from current TF.
228	  RuntimeFallbackOpEntry op_entry;
229	  if (!op_name.consume_front("tf."))
230	    return tfrt::MakeStringError(op_name, " does not start with 'tf.'");
231	  op_entry.op_name.assign(op_name.begin(), op_name.end());
232	  return CoreRuntimeOp(
233	      [op_entry = std::move(op_entry), this](const OpInvocation& invocation) {
234	        // If the op does not have outputs, then it is expected to output an
235	        // out chain.
236	        bool update_chain = invocation.results.empty();
237	
238	        // Convert the argument tensors to RuntimeFallbackTensors.
239	        for (auto& argument : invocation.arguments) {
240	          argument = argument.TransferToSameDevice(
241	              invocation.exec_ctx, RuntimeFallbackTensor::kTensorType);
242	        }
243	
244	        tfrt::ExecuteOnOpHandler<RuntimeFallbackOpHandlerTraits>(
245	            update_chain, invocation, std::move(op_entry), this);
246	      },
247	      // device and arg_tensor_type are not used in runtime fallback ops.
248	      /*is_fallback=*/true, /*device=*/device_);
249	}
