254	  std::unique_ptr<RuntimeFallbackOpHandler> op_handler(
255	      new RuntimeFallbackOpHandler(
256	          runtime, runtime->GetHostContext()->GetHostDeviceRef(),
257	          tf_device_name.str()));
258	  if (auto error = op_handler->Initialize()) {
259	    return std::move(error);
260	  }
261	  auto op_handler_ptr = op_handler.get();
262	  runtime->TakeOpHandler(std::move(op_handler));
263	  return op_handler_ptr;
264	}
