297	  absl::Status RunInternal(
298	      const RunOptions& run_options,
299	      const std::vector<std::pair<std::string, Tensor>>& inputs,
300	      const std::vector<std::string>& output_tensor_names,
301	      const std::vector<std::string>& target_node_names,
302	      std::vector<Tensor>* outputs,
303	      const thread::ThreadPoolOptions& thread_pool_options) {
304	    {
305	      absl::MutexLock lock(session_state_lock_);
306	      if (session_state_ == SessionState::kInitialized) {
307	        return absl::UnavailableError("Session not created yet.");
308	      }
309	      TF_RETURN_IF_ERROR(CheckNotClosedLocked());
310	    }
311	    DCHECK(outputs || output_tensor_names.empty()) << "No outputs in Run()";
312	    // Run the model.
313	    tensorflow::tfrt_stub::GraphExecutionRunOptions
314	        graph_execution_run_options{};
315	    if (run_options.timeout_in_ms() > 0) {
316	      graph_execution_run_options.deadline = absl::ToChronoTime(
317	          absl::Now() + absl::Milliseconds(run_options.timeout_in_ms()));
318	    }
319	
320	    // TODO(b/193913357): Provide a way for this configurable rather than
321	    // hardcoding the work queue.
322	    std::unique_ptr<tensorflow::tfrt_stub::WorkQueueInterface> work_queue;
323	    // For *intra* op thread pool, we always use the one in input arg.
324	    // TODO(juanlishen): Remove unused intra op thread pool creation logic from
325	    // `ThreadPoolManager`.
326	    auto* const intra_op_thread_pool = thread_pool_options.intra_op_threadpool;
327	    // For *inter* op thread pool, we determine it as following.
328	    if (inter_op_thread_pools_.run_in_caller_thread() ||
329	        run_options.inter_op_thread_pool() == -1) {
330	      // Use the caller thread if specified by session or run.
331	      work_queue = tfrt_stub::WrapDefaultWorkQueue(
332	          tfrt::CreateSingleThreadedWorkQueue(), intra_op_thread_pool);
333	    } else if (thread_pool_options.inter_op_threadpool != nullptr) {
334	      // Prefer user-provided thread pool.
335	      work_queue =
336	          std::make_unique<tensorflow::tfrt_stub::TfThreadPoolWorkQueue>(
337	              /*id=*/tfrt::GetUniqueInt(), intra_op_thread_pool,
338	              thread_pool_options.inter_op_threadpool);
339	    } else {
340	      // Check `run_options` to decide thread pool.
341	      TF_ASSIGN_OR_RETURN(auto* thread_pool,
342	                          inter_op_thread_pools_.GetThreadPool(
343	                              run_options.inter_op_thread_pool()));
344	      work_queue =
345	          std::make_unique<tensorflow::tfrt_stub::TfThreadPoolWorkQueue>(
346	              /*id=*/tfrt::GetUniqueInt(), intra_op_thread_pool, thread_pool);
347	    }
348	    graph_execution_run_options.work_queue = work_queue.get();
349	
350	    std::vector<Tensor> output_tensors;
351	    TF_RETURN_IF_ERROR(graph_executor_->Run(
352	        graph_execution_run_options, inputs, output_tensor_names,
353	        target_node_names, &output_tensors));
354	    if (outputs) {
355	      DCHECK_EQ(output_tensors.size(), output_tensor_names.size());
356	      outputs->swap(output_tensors);
357	    } else {
358	      DCHECK(output_tensor_names.empty()) << "No outputs in Run()";
359	    }
360	
361	    return absl::OkStatus();
362	  }
