402	  /// \brief Creates a `handle` for invoking the subgraph defined by
403	  /// `callable_options`.
404	  // NOTE: This API is still experimental and may change.
405	  absl::Status MakeCallable(const CallableOptions& callable_options,
406	                            CallableHandle* out_handle) override {
407	    absl::MutexLock lock(callables_lock_);
408	    *out_handle = next_callable_handle_++;
409	    assert(callables_.find(*out_handle) == callables_.end());
410	    callables_[*out_handle] = {callable_options};
