414	  /// \brief Invokes the subgraph named by `handle` with the given options and
415	  /// input tensors.
416	  ///
417	  /// The order of tensors in `feed_tensors` must and `fetch_tensors` will
418	  /// match the order of names in `CallableOptions::feed()` and
419	  /// `CallableOptions::fetch()` when this subgraph was created.
420	  /// NOTE: This API is still experimental and may change.
421	  absl::Status RunCallable(CallableHandle handle,
422	                           const std::vector<Tensor>& feed_tensors,
423	                           std::vector<Tensor>* fetch_tensors,
424	                           RunMetadata* run_metadata) override {
425	    return RunCallable(handle, feed_tensors, fetch_tensors, run_metadata, {});
426	  }
427	
428	  /// \brief Invokes the subgraph named by `handle` with the given options and
429	  /// input tensors. User can provide custom threadpool implementation via
430	  /// thread_pool_options.
431	  ///
432	  /// The order of tensors in `feed_tensors` must and `fetch_tensors` will
433	  /// match the order of names in `CallableOptions::feed()` and
434	  /// `CallableOptions::fetch()` when this subgraph was created.
435	  /// NOTE: This API is still experimental and may change.
436	  absl::Status RunCallable(
437	      CallableHandle handle, const std::vector<Tensor>& feed_tensors,
438	      std::vector<Tensor>* fetch_tensors, RunMetadata* run_metadata,
439	      const thread::ThreadPoolOptions& thread_pool_options) override {
440	    Callable callable;
441	    {
442	      absl::MutexLock lock(callables_lock_);
443	      auto it = callables_.find(handle);
444	      if (it == callables_.end())
445	        return absl::InvalidArgumentError(
446	            absl::StrCat("No such callable handle: ", handle));
447	      callable = it->second;
448	    }
449	    if (callable.callable_options.feed_size() != feed_tensors.size())
450	      return absl::InvalidArgumentError("Invalid number of feed tensors");
451	
452	    std::vector<std::pair<std::string, Tensor>> inputs;
453	    for (const auto& it :
454	         llvm::zip(callable.callable_options.feed(), feed_tensors)) {
455	      inputs.emplace_back(std::make_pair(std::get<0>(it), std::get<1>(it)));
456	    }
457	    std::vector<std::string> output_tensor_names;
458	    for (const auto& tensor_name : callable.callable_options.fetch()) {
459	      output_tensor_names.emplace_back(tensor_name);
460	    }
461	    std::vector<std::string> target_node_names;
462	    for (const auto& node_name : callable.callable_options.target()) {
463	      target_node_names.emplace_back(node_name);
464	    }
465	
466	    return Run(inputs, output_tensor_names, target_node_names, fetch_tensors);
467	  }
