590	std::unique_ptr<tensorflow::tfrt_stub::WorkQueueInterface>
591	CreateRunHandlerWorkQueue(const TfrtThreadpoolOptions& session_options) {
592	  // Use half of the main threads as the default value for the
593	  // number of complementary threads. The complimentary threads are only used
594	  // for help to process intra ops if the main threads are blocked.
595	  int num_complementary_threads =
596	      std::max(1, session_options.num_main_threads / 2);
597	
598	  tfrt::tf::RunHandlerThreadWorkQueue::Options options;
599	  options.num_main_threads =
600	      session_options.num_main_threads;  // NOMUTANTS--performance tuning
601	  options.num_complementary_threads = num_complementary_threads;
602	  options.init_timeout_ms =
603	      absl::ToInt64Milliseconds(session_options.init_timeout);
604	  options.max_concurrent_handler =
605	      session_options.max_concurrent_handler;  // NOMUTANTS--performance tuning
606	  options.num_sub_thread_pool =
607	      session_options.num_sub_thread_pool;  // NOMUTANTS--performance tuning
608	
609	  // The number of threads in each sub thread pool is not specified,
610	  // we evenly distributed the number of threads to each thread pool by
611	  // default.
612	  std::vector<int> num_threads;
613	  const int num_threads_per_pool =
614	      options.num_main_threads / options.num_sub_thread_pool;
615	
616	  num_threads.resize(options.num_sub_thread_pool - 1, num_threads_per_pool);
617	  num_threads.push_back(options.num_main_threads -
618	                        (options.num_sub_thread_pool - 1) *
619	                            num_threads_per_pool);
620	  options.num_threads_in_sub_thread_pool = num_threads;
621	  options.sub_thread_request_percentage = {1.0};
622	
623	  options.use_adaptive_waiting_time = true;
624	
625	  LOG_FIRST_N(INFO, 10) << "RunHandlerThreadWorkQueue Options: " << options;
626	  return std::make_unique<tfrt::tf::RunHandlerThreadWorkQueue>(options);
627	}
628	}  // namespace
629	
630	// Manages named thread pools used when creating `TfrtSession`.
631	class TfrtSessionFactory::ThreadPoolManager {
632	 public:
633	  // Updates the thread pools based on the given `SessionOptions`. Returns a
634	  // `TfrtSessionInterOpThreadPools` that can be used to create a `TfrtSession`.
635	  absl::StatusOr<TfrtSessionInterOpThreadPools> UpdateAndGetInterOpThreadPools(
636	      const SessionOptions& options) {
637	    if (options.config.inter_op_parallelism_threads() > 0) {
638	      LOG(WARNING) << "TFRT session does not support positive "
639	                      "inter_op_parallelism_threads for now";
640	    }
641	    if (options.config.use_per_session_threads()) {
642	      return absl::InvalidArgumentError(
643	          "TFRT session does not yet support use_per_session_threads()");
644	    }
645	
646	    auto session_inter_op_thread_pool_size =
647	        options.config.session_inter_op_thread_pool_size();
648	
649	    if (session_inter_op_thread_pool_size > 0) {
650	      TfrtSessionInterOpThreadPools inter_op_thread_pools{
651	          session_inter_op_thread_pool_size, /*run_in_caller_thread=*/false};
652	
653	      for (const auto& it :
654	           llvm::enumerate(options.config.session_inter_op_thread_pool())) {
655	        const ThreadPoolOptionProto& pool_options = it.value();
656	        auto pool_index = it.index();
657	        auto num_threads = pool_options.num_threads();
658	
659	        if (num_threads != 0) {
660	          TF_ASSIGN_OR_RETURN(
661	              auto* thread_pool,
662	              GetOrCreateThreadPool(options.env, pool_options, pool_index));
663	          inter_op_thread_pools.SetThreadPool(pool_index, thread_pool);
664	        } else {
665	          // TODO(juanlishen): To be consistent with `DirectSession`, we should
666	          // pick an appropriate `num_threads` and create a new thread pool in
667	          // this case.
668	          inter_op_thread_pools.SetThreadPool(pool_index,
669	                                              GlobalThreadPool(options));
670	        }
671	      }
672	      return inter_op_thread_pools;
673	    } else if (options.config.inter_op_parallelism_threads() < 0) {
674	      return TfrtSessionInterOpThreadPools{/*size=*/0,
675	                                           /*run_in_caller_thread=*/true};
676	    } else if (session_inter_op_thread_pool_size == 0) {
677	      // If session_inter_op_thread_pool_size is 0, add a default thread pool
678	      // option, so the behavior is consistent with DirectSession.
679	      TfrtSessionInterOpThreadPools session_thread_pool_options{
680	          /*size=*/1, /*run_in_caller_thread=*/false};
681	      session_thread_pool_options.SetThreadPool(0, GlobalThreadPool(options));
682	      return session_thread_pool_options;
683	    } else {
684	      return absl::InvalidArgumentError(
685	          "session_inter_op_thread_pool_size must be >= 0");
686	    }
687	  }
688	
689	 private:
690	  class ThreadPoolWithNumThreads {
691	   public:
692	    // `thread_pool` must be non-null.
693	    ThreadPoolWithNumThreads(int num_thread,
694	                             std::unique_ptr<thread::ThreadPool> thread_pool)
695	        : num_threads_(num_thread),
696	          thread_pool_(std::move(thread_pool)),
697	          thread_pool_interface_wrapper_(
698	              ABSL_DIE_IF_NULL(thread_pool_)->AsEigenThreadPool()) {}
699	
700	    int num_threads() const { return num_threads_; }
701	
702	    ThreadPoolInterfaceWrapper* thread_pool_interface_wrapper() {
703	      return &thread_pool_interface_wrapper_;
704	    }
705	
706	   private:
707	    int num_threads_;
708	    std::unique_ptr<thread::ThreadPool> thread_pool_;
709	    ThreadPoolInterfaceWrapper thread_pool_interface_wrapper_;
710	  };
711	
712	  // Returns a per-process global thread pool, configured by the first session
713	  // in the process.
714	  ThreadPoolInterfaceWrapper* GlobalThreadPool(const SessionOptions& options) {
715	    static thread::ThreadPool* const thread_pool =
716	        NewThreadPoolFromSessionOptions(options);
717	    static auto* const wrapper =
718	        new ThreadPoolInterfaceWrapper{thread_pool->AsEigenThreadPool()};
719	    return wrapper;
720	  }
721	
722	  // Returns a `ThreadPoolInterfaceWrapper` that wraps the thread pool with the
723	  // name in `pool_options`. Creates and stores a new thread pool if an existing
724	  // one can't be found.
725	  absl::StatusOr<ThreadPoolInterfaceWrapper*> GetOrCreateThreadPool(
726	      Env* env, const ThreadPoolOptionProto& pool_options, int pool_index) {
727	    const int32_t num_threads = pool_options.num_threads();
728	    CHECK_GT(num_threads, 0);
729	
730	    const std::string& name = pool_options.global_name();
731	    if (name.empty()) {
732	      return absl::InvalidArgumentError(
733	          "TFRT session does not yet support session local thread pool");
734	    }
735	
736	    absl::MutexLock lock(mutex_);
737	
738	    auto it = named_thread_pools_.find(name);
739	    // The thread pool with the given name already exists.
740	    if (it != named_thread_pools_.end()) {
741	      if (it->second->num_threads() != num_threads) {
742	        return absl::InvalidArgumentError(absl::StrCat(
743	            "TfrtSession thread pool ", name,
744	            " configured previously with num_threads=",
745	            it->second->num_threads(),
746	            "; cannot re-configure with num_threads=", num_threads));
747	      }
748	      return it->second->thread_pool_interface_wrapper();
749	    }
750	
751	    // The thread pool with the given name does not yet exist. Create one.
752	    auto thread_pool = std::make_unique<thread::ThreadPool>(
753	        env, ThreadOptions(), absl::StrCat("TfrtSessionInter", pool_index),
754	        num_threads, /*low_latency_hint=*/false,
755	        /*allocator=*/nullptr);
756	    auto ret = named_thread_pools_.emplace(
757	        name, std::make_unique<ThreadPoolWithNumThreads>(
758	                  num_threads, std::move(thread_pool)));
759	    CHECK(ret.second);
760	
761	    return ret.first->second->thread_pool_interface_wrapper();
762	  }
763	
764	  mutable absl::Mutex mutex_;
765	  // For pointer-stability of the map value (when calling
766	  // `thread_pool_interface_wrapper()`), we add a layer of indirection.
767	  absl::flat_hash_map<std::string, std::unique_ptr<ThreadPoolWithNumThreads>>
768	      named_thread_pools_ ABSL_GUARDED_BY(mutex_);
769	};
770	
771	TfrtSessionFactory::TfrtSessionFactory()
772	    : thread_pool_manager_(std::make_unique<ThreadPoolManager>()) {}
773	
774	// Holds an initializer, which should only be registered before main executes.
775	// As an internal component of `TfrtSessionFactory`, it does not take
776	// responsibility for thread safety. (`TfrtSessionFactory` does).
777	class InitializerRegistry {
778	 public:
779	  static InitializerRegistry& Get() {
780	    static auto* reg = new InitializerRegistry();
781	    return *reg;
782	  }
783	
784	  void Register(TfrtSessionFactory::RuntimeInitializer initializer) {
785	    DCHECK(initializer_ == nullptr);
786	    initializer_ = initializer;
787	  }
788	
789	  absl::Status RunInitializer(tfrt_stub::Runtime* runtime) {
790	    LOG(INFO) << "Running Initializer within TfrtSessionFactory.";
791	    TF_RETURN_IF_ERROR(initializer_ ? initializer_(runtime) : absl::OkStatus());
792	    return absl::OkStatus();
793	  }
794	
795	 private:
796	  TfrtSessionFactory::RuntimeInitializer initializer_;
797	};
798	
799	void TfrtSessionFactory::RegisterInitializer(RuntimeInitializer initializer) {
800	  InitializerRegistry::Get().Register(std::move(initializer));
801	}
802	
803	absl::Status TfrtSessionFactory::InitializeLocked(
804	    const TfrtSessionOptions& options) {
805	  mutex_.AssertHeld();
806	  if (options.backend_compiler) {
807	    backend_compiler_ = options.backend_compiler;
808	  }
809	  if (options.use_tpu) {
810	    DCHECK(!options.use_gpu);
811	    device_target_ = TfrtDeviceInfraTarget::kTpurt;
812	    if (!options.backend_compiler) {
813	      tpu_use_tpu_runner_ = true;
814	    }
815	  } else if (options.use_gpu) {
816	    device_target_ = TfrtDeviceInfraTarget::kGpu;
817	    if (!options.backend_compiler) {
818	      use_gpu_ = true;
819	    }
820	  }
821	
822	  LOG(INFO) << "Start initializing TfrtSession";
823	  if (options.runtime != nullptr) {
824	    runtime_ = options.runtime;
825	  } else if (runtime_ == nullptr) {
826	    owned_runtime_ = tensorflow::tfrt_stub::Runtime::Create(
827	        CreateRunHandlerWorkQueue(options.threadpool_options),
828	        options.diag_handler);
829	    runtime_ = owned_runtime_.get();
830	  }
831	  enable_mlrt_ = options.enable_mlrt;
832	  enable_async_native_lowering_ = options.enable_async_native_lowering;
833	  enable_tpu_host_allocator_for_inputs_ =
834	      options.enable_tpu_host_allocator_for_inputs;
835	  return absl::OkStatus();
836	}
837	
838	bool TfrtSessionFactory::AcceptsOptions(const SessionOptions& options) {
839	  if (options.target == "tfrt_session") return true;
840	  if (options.target.empty()) {
841	    return options.config.experimental().use_tfrt() ||
842	           GetDefaultLocalSessionImpl() == LocalSessionImpl::kTfrtSession;
843	  }
844	  return false;
845	}
846	
847	absl::Status TfrtSessionFactory::NewSession(const SessionOptions& options,
848	                                            Session** out_session)
849	    TF_LOCKS_EXCLUDED(mutex_) {
850	  // TODO(b/206499043): `SessionOptions` should be passed to Saved Model to
851	  // create `FallbackState`.
852	  if (options.config.intra_op_parallelism_threads() != 0) {
853	    LOG(WARNING) << "TFRT session ignores intra_op_parallelism_threads. "
854	                    "Intra-op thread "
855	                    "pool can only be configured by `Run()`";
856	  }
857	
858	  *out_session = nullptr;
859	
860	  absl::MutexLock lock(mutex_);
861	  std::vector<std::unique_ptr<Device>> devices;
862	  TF_RETURN_IF_ERROR(DeviceFactory::AddDevices(
863	      options, "/job:localhost/replica:0/task:0", &devices));
864	  device_manager_ = std::make_unique<StaticDeviceMgr>(std::move(devices));
865	  if (!IsInitialized()) {
866	    TF_RETURN_IF_ERROR(InitializeLocked({}));
867	    TF_RETURN_IF_ERROR(InitializerRegistry::Get().RunInitializer(runtime_));
868	  }
869	
870	  TF_ASSIGN_OR_RETURN(
871	      auto inter_op_thread_pools,
872	      thread_pool_manager_->UpdateAndGetInterOpThreadPools(options));
873	
874	  *out_session = new TfrtSession(
875	      options, runtime_, device_target_, tpu_use_tpu_runner_, use_gpu_,
876	      std::move(inter_op_thread_pools), enable_mlrt_,
877	      enable_async_native_lowering_, enable_tpu_host_allocator_for_inputs_,
878	      backend_compiler_, std::move(device_manager_));
879	  return absl::OkStatus();
880	}
881	
882	namespace {
883	static TfrtSessionFactory* session_factory = nullptr;
884	}
885	
886	tfrt_stub::Runtime* TfrtSessionFactory::GetRuntime() {
887	  DCHECK(session_factory != nullptr);
888	  absl::MutexLock lock(session_factory->mutex_);
889	  return session_factory->runtime_;
890	}
891	
892	absl::Status InitializeTfrtSession(const TfrtSessionOptions& options) {
893	  DCHECK(session_factory != nullptr);
894	  absl::MutexLock lock(session_factory->mutex_);
895	  DCHECK(!session_factory->IsInitialized());
896	  return UpdateTfrtSessionOptionsLocked(options);
897	}
898	
899	absl::Status UpdateTfrtSessionOptionsLocked(const TfrtSessionOptions& options) {
900	  DCHECK(session_factory != nullptr);
901	  session_factory->mutex_.AssertHeld();
902	  return session_factory->InitializeLocked(options);
903	}
